-- Market-channel releases on the SDKWork storefront channel.
INSERT INTO appstore_market_release
    (id, tenant_id, organization_id, app_id, listing_id, release_id, channel_id, market_release_no, external_app_id, external_release_id, external_track, market_status, rollout_percent, countries_json, store_url, external_status_json, submitted_at, approved_at, released_at, rejected_at, last_synced_at, created_at, updated_at)
SELECT
    'mrel-' || r.id,
    r.tenant_id,
    r.organization_id,
    l.app_id,
    r.listing_id,
    r.id,
    'mch-sdkwork-pc',
    'MR-' || UPPER(REPLACE(r.id, '-', '')),
    l.app_key,
    r.version_code,
    'production',
    'published',
    100,
    '["CN", "US"]',
    'https://appstore.sdkwork.local/apps/' || l.listing_slug,
    '{"syncState": "seeded"}',
    r.submitted_at,
    r.approved_at,
    r.published_at,
    NULL,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM appstore_release r
JOIN appstore_listing l
  ON l.id = r.listing_id
 AND l.tenant_id = r.tenant_id
WHERE r.tenant_id = '100001'
  AND r.release_status = 'published'
  AND r.id IN (
    'rel-sdkwork-account-pc-010',
    'rel-sdkwork-agents-flutter-mobile-010',
    'rel-sdkwork-agents-h5-010',
    'rel-sdkwork-agents-harmony-mobile-010',
    'rel-sdkwork-agents-mini-program-010',
    'rel-sdkwork-agents-pc-000',
    'rel-sdkwork-aiot-h5-010',
    'rel-sdkwork-aiot-mini-program-010',
    'rel-sdkwork-aiot-pc-010',
    'rel-sdkwork-appstore-flutter-mobile-010',
    'rel-sdkwork-appstore-h5-100',
    'rel-sdkwork-appstore-harmony-mobile-010',
